BEGIN READ ONLY; SELECT jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'fingerprint',md5(jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,pg_get_userbyid(c.relowner))::text))) AS catalog FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','credentialing') AND c.relkind IN ('r','p','v','m','S','f'); COMMIT;
